  toffoli_gate  u8 (.a(b1_1), .b(g0_2), .c(t2_0), .p(b1_2), .q(g0_3), .r(t2_1));
  toffoli_gate  u9 (.a(b1_2), .b(t1_2), .c(t3_0), .p(b1_3), .q(t1_3), .r(t3_1));
  feynman_gate  u10 (.a(b1_3), .b(k1_2), .p(b1_4), .q(k1_3));
  feynman_gate  u11 (.a(g1_1), .b(k2_0), .p(g1_2), .q(k2_1));
  feynman_gate  u12 (.a(t2_1), .b(k2_1), .p(t2_2), .q(k2_2));
  feynman_gate  u13 (.a(t3_1), .b(k2_2), .p(t3_2), .q(k2_3));
  toffoli_gate  u14 (.a(b2_1), .b(g1_2), .c(t4_0), .p(b2_2), .q(g1_3), .r(t4_1));
  toffoli_gate  u15 (.a(b2_2), .b(t2_2), .c(t5_0), .p(b2_3), .q(t2_3), .r(t5_1));
  toffoli_gate  u16 (.a(b2_3), .b(t3_2), .c(t6_0), .p(b2_4), .q(t3_3), .r(t6_1));
  feynman_gate  u17 (.a(b2_4), .b(k2_3), .p(b2_5), .q(k2_4));
  feynman_gate  u18 (.a(t4_1), .b(g2_1), .p(t4_2), .q(g2_2));
  feynman_gate  u19 (.a(t5_1), .b(g2_2), .p(t5_2), .q(g2_3));
  feynman_gate  u20 (.a(t6_1), .b(g2_3), .p(t6_2), .q(g2_4));
  peres_gate    u21 (.a(b3_1), .b(g2_4), .c(g3_1), .p(b3_2), .q(g2_5), .r(g3_2));

  assign sum[0] = c0_1;
  assign sum[1] = k1_3;
  assign sum[2] = k2_4;
  assign sum[3] = g2_5;
  assign cout = g3_2;

  // Garbage outputs (not used): a0_1, a1_1, a2_1, a3_1, b0_2, b1_4, b2_5, b3_2, g0_3, g1_3, t1_3, t2_3, t3_3, t4_2, t5_2, t6_2
endmodule

// Ripple-carry adder with carry-out, two Peres gates per bit.
// Gates: 8 Peres.  Ancilla inputs: 4.  Garbage outputs: 8.
module rca_peres (
  input  [3:0] a,
  input  [3:0] b,
  input        cin,
  output [3:0] sum,
  output       cout
);
  wire a0_0, a1_0, a2_0, a3_0, b0_0, b1_0, b2_0, b3_0;
  wire c0_0, z0_0, z1_0, z2_0, z3_0, a0_1, b0_1, z0_1;
  wire b0_2, c0_1, z0_2, a1_1, b1_1, z1_1, b1_2, z0_3;
  wire z1_2, a2_1, b2_1, z2_1, b2_2, z1_3, z2_2, a3_1;
  wire b3_1, z3_1, b3_2, z2_3, z3_2;

  assign a0_0 = a[0];         // primary input
  assign a1_0 = a[1];         // primary input
  assign a2_0 = a[2];         // primary input
  assign a3_0 = a[3];         // primary input
  assign b0_0 = b[0];         // primary input
  assign b1_0 = b[1];         // primary input
  assign b2_0 = b[2];         // primary input
  assign b3_0 = b[3];         // primary input
  assign c0_0 = cin;          // primary input
  assign z0_0 = 1'b0;         // ancilla, constant 0
  assign z1_0 = 1'b0;         // ancilla, constant 0
  assign z2_0 = 1'b0;         // ancilla, constant 0
  assign z3_0 = 1'b0;         // ancilla, constant 0

  peres_gate    u1 (.a(a0_0), .b(b0_0), .c(z0_0), .p(a0_1), .q(b0_1), .r(z0_1));
  peres_gate    u2 (.a(b0_1), .b(c0_0), .c(z0_1), .p(b0_2), .q(c0_1), .r(z0_2));
  peres_gate    u3 (.a(a1_0), .b(b1_0), .c(z1_0), .p(a1_1), .q(b1_1), .r(z1_1));
  peres_gate    u4 (.a(b1_1), .b(z0_2), .c(z1_1), .p(b1_2), .q(z0_3), .r(z1_2));
  peres_gate    u5 (.a(a2_0), .b(b2_0), .c(z2_0), .p(a2_1), .q(b2_1), .r(z2_1));
  peres_gate    u6 (.a(b2_1), .b(z1_2), .c(z2_1), .p(b2_2), .q(z1_3), .r(z2_2));
  peres_gate    u7 (.a(a3_0), .b(b3_0), .c(z3_0), .p(a3_1), .q(b3_1), .r(z3_1));
  peres_gate    u8 (.a(b3_1), .b(z2_2), .c(z3_1), .p(b3_2), .q(z2_3), .r(z3_2));

  assign sum[0] = c0_1;
  assign sum[1] = z0_3;
  assign sum[2] = z1_3;
  assign sum[3] = z2_3;
  assign cout = z3_2;

  // Garbage outputs (not used): a0_1, a1_1, a2_1, a3_1, b0_2, b1_2, b2_2, b3_2
endmodule
